def repeatedRows(matrix):
    from collections import defaultdict
    row_dict = defaultdict(list)
    result = []

    for i, row in enumerate(matrix):
        row_tuple = tuple(row)
        row_dict[row_tuple].append(i)

    for indices in row_dict.values():
        if len(indices) > 1:
            result.extend(indices[1:])

    return result
